using System;using System.IO;using System.Threading;
class ScannerChecks{static void Main(string[] args){var folder=args[0];Directory.CreateDirectory(folder);for(int i=0;i<520;i++)File.WriteAllText(Path.Combine(folder,"File-"+i+".txt"),"index");var cancel=new CancellationTokenSource();bool stopped=false;try{LibrarySourceScanner.Scan(folder,null,cancel.Token,n=>cancel.Cancel());}catch(OperationCanceledException){stopped=true;}if(!stopped)throw new Exception("Scan did not stop after progress cancellation");var normal=LibrarySourceScanner.Scan(folder);if(normal.Files.Count!=520||!normal.Complete)throw new Exception("Normal scan lost originals");Console.WriteLine("Scanner progress, cancellation and complete rescan passed.");}}
